55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	};
66	
67	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
68	
69	const policyBasePremium = (items: Item[]): number =>
70	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
71	
72	const withFirstInsuranceSurcharge = (policyBase: number): number =>
73	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
74	
75	const quotePremium = (items: Item[]): number =>
76	  Math.ceil(withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE);
77	
78	const runStep = (step: Step): StepResult => {
79	  if (step.op === "quote") {
80	    return { premium: quotePremium(step.items) };
81	  }
82	  throw new Error(`Unsupported step: ${step.op}`);
83	};
84	
85	export const runScenario = (scenario: Scenario): ScenarioResult => ({
86	  results: scenario.steps.map(runStep),
87	});
